type TreeNode = { v: number; L: TreeNode | null; R: TreeNode | null };
// Level-order array, null for a missing child.
function buildTree(values: (number | null)[]): TreeNode | null {
  if (!values.length || values[0] == null) return null;
  const root: TreeNode = { v: values[0], L: null, R: null };
  const q = [root];
  let i = 1;
  while (q.length && i < values.length) {
    const cur = q.shift()!;
    const l = values[i++];
    if (l != null) { cur.L = { v: l, L: null, R: null }; q.push(cur.L); }
    const r = values[i++];
    if (r != null) { cur.R = { v: r, L: null, R: null }; q.push(cur.R); }
  }
  return root;
}

function splitPoint(root: TreeNode | null, a: number, b: number): number | null {
  const lo = Math.min(a, b), hi = Math.max(a, b);
  let cur = root;
  while (cur) {
    if (hi < cur.v) cur = cur.L;
    else if (lo > cur.v) cur = cur.R;
    else return cur.v;
  }
  return null;
}

function splitPointFrom(values: (number | null)[], a: number, b: number): number | null {
  return splitPoint(buildTree(values), a, b);
}
